from pathlib import Path
import json
O=Path(__file__).resolve().parent
rows=[]
def add(a,name,summary,*details,subsystem='graphics'):
 rows.append(dict(module='server',address='0x'+a,proposed_name=name,subsystem=subsystem,summary_ru=summary,confidence='high',details_ru=list(details),evidence_paths=[f'decompiled/server/partial-pass/functions/0x{a}.c',f'analysis/server-event-effects/{a}-0.asm','analysis/server-event-effects/evidence.json','analysis/server-event-effects/contract.md']))
add('10117770','CreateBloodShotParticleIfAllowed','Создаёт env_particle с aurora/blood_shot.aur после violence/color/count проверок.',
 'cdecl(origin*, unused DWORD, color, count, velocity xyz by value). Сначала 1011a120(color); затем color!=-1 и count!=0. Второй аргумент вообще не читается; count, включая отрицательный, только gate и не задаёт размер или число частиц.',
 '10094060 получает string_t=(literal101e580c-global.stringbase), enabled=1, origin by value, skin=0, delay=0.25f, unused DWORD=0, velocity by value. Helper сам не пишет temp-entity payload; параметры color/count не передаются в Particle message. Результат factory игнорируется. Origin NULL проверяется только косвенно достижимостью ветви, отдельного guard нет.',
 'Event support 1011f900 преобразует float size через CVTTSS2SI; значения60/45 дают ненулевой gate, а не разный масштаб в этом callee. Полный клиентский renderer aurora остаётся за пределами server packet.')
add('1011a120','BloodColor_ViolenceCvarEnabled','Выбирает violence_hblood для color247, violence_ablood для остальных допустимых цветов.',
 'cdecl(color), EAX0/1. Color==-1 сразу0. Color247 использует violence_hblood, любой иной color — violence_ablood. Engine CVarGetFloat slot57 возвращает ST0, native FSTP округляет в float перед сравнением с0.',
 'UCOMISS/LAHF/TEST44/JNP различает ordered zero от nonzero/unordered: +0 и -0 дают0, ненулевой результат и NaN дают1 при продолжающемся исполнении. Это не проверка cvar>0 и не bool из engine ABI.')
add('10094060','CParticle_CreateConfigured','Выделяет particle, задаёт поля, вызывает Spawn, сообщает клиентам и опционально планирует KillParticle.',
 'cdecl, EAX particle. Native stack layout: string_t, enabled DWORD (читается только low byte), origin xyz by value, skin DWORD, delay float, unused DWORD, velocity xyz by value — всего44 bytes. 10092020(0) даёт private object, NULL не проверяется; 10119fe0 устанавливает origin.',
 'Spawnflags заменяется на enabled.lowByte!=0, skin получает аргумент. Если хотя бы velocity component ненулевой или NaN, skin=666, movetype=5, velocity копируется. Message+1d8 получает string_t, затем virtual+2c. Concrete CParticle Spawn1009efc0 безусловно перезаписывает movetype=0, но не skin/velocity: промежуточное movetype5 нельзя выдавать за окончательную server physics.',
 'Ищет первую entity classname player через10118460(NULL,"player"), разрешает private через100125e0(pev); при nonNULL вызывает particle.virtual+118(player). Concrete1009bbf0 игнорирует player и отправляет destination2 broadcast, поэтому отсутствие найденного player пропускает сообщение, но не создание entity.',
 'Float delay конвертируется double и сравнивается с native double0.1; ordered delay>=0.1 планирует virtual+8(delay), затем Think+78=100984f0. NaN и меньшие значения не ставят этот callback. Последним действием classname меняется на string_t env_particle. Нет записи входного unused DWORD (stack+24h), fuser1 или собственного освобождения памяти.')
add('10092020','CParticle_ResolveOrAllocatePrivateData','Возвращает существующие private data либо выделяет CParticle размером DCh.',
 'cdecl(entvars*), EAX pointer несмотря на void Ghidra. При NULL entvars CreateEntity, при успехе edict+80h. Если entvars.containingedict+20ch ненулевой и edict+7ch private!=NULL, возвращает его без class/vtable проверки.',
 'Иначе PvAllocEntPrivateData(edict,DCh); при успехе пишет vtable101bff80 и object+4=entvars. RTTI COL подтверждает CParticle. Нет собственного zero-fill/полного constructor. CreateEntity failure оставляет dereference NULL+20ch; allocation failure явно XOR EAX,EAX; MOV[EAX+4],ESI, а не безопасный returnNULL.')
add('1009efc0','CParticle_Spawn','Инициализирует неподвижную entity-носитель particle с моделью sprites/null.spr.',
 'Thiscall, RET. Пишет pev.solid=0, movetype=0, renderamt=128.0, rendermode=2, body=spawnflags&1. Вызывает virtual+30, затем10119fe0(this,&pev.origin), затем engine SetModel(edict,"sprites/null.spr").',
 'Raw CParticle vtable101bff80+2c указывает сюда; +30=10099830. В этой функции нет чтения skin/velocity и нет загрузки aurora definition. Окончательный movetype0 перекрывает предшествующую запись5 в10094060; renderamt128 здесь не является последующим fade.')
add('10099830','CParticle_PrecacheNullSprite','Передаёт sprites/null.spr существующему helper предварительной загрузки модели.',
 'Native PUSH literal101b82a0; CALL10116990; POP ECX; RET. ECX=this не читается, аргументов на входном стеке нет. Concrete vtable101bff80+30 связывает эту функцию со Spawn.',
 'Support10116990 проверяет имя/файл через engine LoadFileForMe/FreeFile и затем PrecacheModel; wrapper не проверяет возвращённый индекс и сам не загружает .aur. Не описывается как прямой вызов PrecacheModel без проверок callee.')
add('1009bbf0','CParticle_BroadcastDefinition','Отправляет Particle usermessage с entity index, именем эффекта и фиксированным суффиксом.',
 'Thiscall(this, ignored player*), RET4; stack argument не читается. MessageBegin(2,global10226490,NULL,NULL), WriteShort(IndexOfEdict(this.pev.edict)), WriteString(stringbase+pev.message), WriteByte(0), WriteString("nah"), WriteShort(-1), MessageEnd. Literal101c2d70 — именно nah, не пустая строка.',
 'Registration100e5fc0 задаёт global10226490=RegUserMsg("Particle",-1). Payload при обычном engine encoding:2+(N+1)+1+4+2=N+10 bytes, N=байтовая длина первой строки доNUL; entity index идёт SHORT, не BYTE. Числовой runtime message ID не фиксирован. Destination2 и NULL recipient не являются unicast найденному player.',
 'Не передаёт origin/velocity/skin/body в этом сообщении. Их возможное потребление через entity updates и смысл nah/-1 требуют клиентского consumer; нельзя объявлять весь particle renderer восстановленным.')
add('100984f0','CParticle_KillParticle','Отключает body и назначает последующее SUB_Remove с задержкой из fuser1 либо1.',
 'Thiscall, RET. Body+114h=0. Если pev.fuser1+258h ordered равен0, virtual+8(1.0f); иначе virtual+8(fuser1), включая отрицательное/NaN при продолжающемся исполнении. Затем Think+78=101028e0.',
 'Raw vtable +8=1000e1f0, далее +4=10017110 ScheduleThinkAfter(delay,0). Собственных clamp, MessageBegin/DelPart или освобождения private data нет; удаление и engine lifetime находятся в ранее REVIEW SUB_Remove. Producer10094060 fuser1 не инициализирует, поэтому конкретную вторую задержку для всех created particles из этого тела вывести нельзя.')
add('1008ac50','CBaseEntity_SUB_StartFadeOutScheduleRemove','Назначает SUB_Remove через virtual scheduler с задержкой0.2f; прозрачность не изменяет.',
 'Thiscall, RET. Единственные действия: virtual+8(0.2f) с native float bits3e4ccccd, затем Think+78=101028e0. Нет записи renderamt/rendermode/body, промежуточных fade steps или отдельного FadeOut callback.',
 'При базовом scheduler binding1000e1f0→virtual+4(0.2f,0)→10017110 используются его clock/parent-assist правила. Универсальная гарантия исполнения ровно через0.2 секунды не доказана: overrides и engine frames остаются внешними. SUB_Remove уже REVIEW; повторная карточка ему не создаётся.',subsystem='entity-core')
add('1011a820','TraceLine_ComposeMonsterGlassFlags','Собирает native TraceLine flags из двух параметров и передаёт пять engine аргументов.',
 'cdecl(start*,end*,mode,glassFlag,skipEdict,TraceResult*), RET. Engine slot31 получает start,end,((mode==1)?1:0)|((glassFlag!=0)?100h:0),skipEdict,result. Первое условие строго equality1; другие ненулевые mode не устанавливают bit0. NEG/SBB корректно трактует любой ненулевой glassFlag.',
 'Нет локальных null checks, инициализации result или преобразования origin. Это server wrapper, не восстановленная реализация engine trace. Splash caller передаёт mode1,glassFlag0 и собственный edict; структура result используется с fraction+10h/endPos+14h согласно ABI и SDK.',subsystem='abi')
add('1011a2f0','Entity_TryWaterRippleAndSplashSound','Проверяет воду трассировкой от глаз вниз, вызывает Ripple producer и опционально воспроизводит всплеск.',
 'cdecl(entity*,soundMode), RET. Требует entity!=NULL, pev.edict!=NULL и EntOffsetOfPEntity(edict)!=0; pevNULL отдельно не проверяется. Start=origin+view_ofs, end=start-(0,0,100). Trace1011a820(start,end,1,0,ownEdict,result). Только ordered fraction==1 прекращает путь; NaN проходит это сравнение. Далее PointContents(result.endPos) должен быть -3.',
 'Вызывает1011ac00, реально передавая entity pointer и ещё12bytes из ТРИЖДЫ скопированных raw bits этого же pointer, а не физические coordinates. Callee читает только первый entity argument; лишние12bytes игнорируются. Он повторяет trace и может не отправить сообщение, но caller не проверяет результат.',
 'После первого успешного gate: soundMode1/2/3 выбирает player/water_small_splash.wav, player/water_splash.wav, player/water_jump.wav. RandomLong(-5,5)+100; EmitSound(edict,channel0,path,1.0,0.8,0,pitch). Любой иной mode, включая0 в monster events, не добавляет звук, но Ripple попытка уже выполнена. Нельзя называть EntOffset gate проверкой client index.')
add('1011ac00','Entity_EmitRippleAtWaterExit','Повторно трассирует от глаз, ищет первый nonwater уровень по Z и отправляет Ripple.',
 'cdecl(entity*, дополнительные stack bytes не читаются), RET. Без NULL/edict guard строит start=origin+view_ofs,end=start-(0,0,100), TraceLine flags1 skip own edict. Ordered fraction==1 завершает путь; затем PointContents(endPos)==-3. Копирует endPos и снова вызывает PointContents.',
 'Пока contents==-3, повышает float z на1.0 и повторяет PointContents. Нет собственного лимита итераций/высоты/проверки progress или NaN. Отправляется первый проверенный nonwater position, а не обязательно точная геометрическая поверхность.',
 'MessageBegin(2,global10226644,NULL,NULL); WriteCoord(x),WriteCoord(y),WriteCoord(z),WriteShort(40),MessageEnd. Registration100e5fc0: RegUserMsg("Ripple",-1). При обычном engine encoding payload8bytes:3x16-bit COORD затем16-bit SHORT. Реальный runtime ID не фиксирован; смысл40 на клиенте и визуальный эффект здесь не выведены.')
(O/'notes.json').write_text(json.dumps({'functions':rows},ensure_ascii=False,indent=2)+'\n',encoding='utf8')
